#!/usr/bin/env python3
"""命令文档生成器：读双语命令注册表 → ASCII 命令树 + Mermaid 流程图。

用法::

    python tools/gen_command_docs.py                 # 打印双语 ASCII 树 + Mermaid
    python tools/gen_command_docs.py --out FILE      # 写入 Markdown
    python tools/gen_command_docs.py --check FILE    # 校验 FILE 含同一生成块（漂移即非 0）

单一真源 = ``core/command_registry.py``；生成块用固定标记包裹，文档侧可直接粘贴：

    <!-- BEGIN: COMMAND_TREE (generated by tools/gen_command_docs.py) -->
    ...
    <!-- END: COMMAND_TREE -->

不生成 HTML/WebUI（用户 2026-11-13 裁决：图片版随 help 走，不做交互网页）。
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import List

BEGIN = "<!-- BEGIN: COMMAND_TREE (generated by tools/gen_command_docs.py) -->"
END = "<!-- END: COMMAND_TREE -->"

# 允许直接 `python tools/gen_command_docs.py`（脚本目录不在 sys.path 时补插件根）。
_PLUGIN_ROOT = Path(__file__).resolve().parent.parent
if str(_PLUGIN_ROOT) not in sys.path:
    sys.path.insert(0, str(_PLUGIN_ROOT))

from core import command_registry as registry  # noqa: E402


def generated_markdown() -> str:
    """完整生成块（标记 + ASCII 双语树 + Mermaid）。"""
    lines = [
        BEGIN,
        "## 命令面（自动生成，勿手改）",
        "",
        f"双根：`{registry.ROOTS['en']}`（英文）· `{registry.ROOTS['cn']}`（全中文）。",
        f"命令组 {len(registry.GROUPS)} 个、叶子命令 {len(registry.COMMANDS)} 条、"
        f"help 1 条；权限两级 public/admin。",
        "",
        "### ASCII 命令树（双语）",
        "",
        "```text",
        "# EN",
        registry.ascii_tree("en"),
        "",
        "# CN",
        registry.ascii_tree("cn"),
        "```",
        "",
        "### Mermaid 流程图（EN/CN 双标）",
        "",
        registry.mermaid(),
        "",
        END,
    ]
    return "\n".join(lines)


def check_file(path: Path) -> int:
    """校验文件含完整生成块；缺失/漂移返回 1。"""
    if not path.is_file():
        print(f"[FAIL] 文件不存在: {path}")
        return 1
    text = path.read_text(encoding="utf-8", errors="replace")
    if BEGIN not in text or END not in text:
        print(f"[FAIL] 缺少生成块标记: {path}")
        return 1
    start = text.index(BEGIN)
    end = text.index(END, start) + len(END)
    found = text[start:end].replace("\r\n", "\n").rstrip()
    expected = generated_markdown().replace("\r\n", "\n").rstrip()
    if found != expected:
        print(f"[FAIL] 命令文档漂移（重新运行 --out 生成）: {path}")
        return 1
    print(f"[OK] 命令文档与注册表一致: {path}")
    return 0


def write_file(path: Path) -> int:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(generated_markdown() + "\n", encoding="utf-8")
    print(f"[OK] 已写入 {path}")
    return 0


def main(argv: List[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="生成双语命令树与 Mermaid 流程图")
    parser.add_argument("--out", type=Path, help="写入 Markdown 文件")
    parser.add_argument("--check", type=Path, help="校验文件内生成块与注册表一致")
    parser.add_argument("--tree", action="store_true", help="只打印 ASCII 双语树")
    parser.add_argument("--mermaid", action="store_true", help="只打印 Mermaid")
    args = parser.parse_args(argv)

    if args.check:
        return check_file(args.check)
    if args.out:
        return write_file(args.out)
    if args.tree:
        print(registry.bilingual_tree())
        return 0
    if args.mermaid:
        print(registry.mermaid())
        return 0
    print(generated_markdown())
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
